import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { Trip } from '../models/trip';

@Injectable({
  providedIn: 'root'
})
export class TripService {
  private apiUrl = 'http://localhost:3000/api/trips';

  constructor(private http: HttpClient) {}

  // Get all trips (public endpoint)
  getTrips(): Observable<Trip[]> {
    return this.http.get<Trip[]>(this.apiUrl)
      .pipe(
        catchError(this.handleError)
      );
  }

  // Get single trip by ID (public endpoint)
  getTrip(id: string): Observable<Trip> {
    return this.http.get<Trip>(`${this.apiUrl}/${id}`)
      .pipe(
        catchError(this.handleError)
      );
  }

  // Create new trip (protected endpoint - requires authentication)
  createTrip(trip: Trip): Observable<any> {
    const headers = new HttpHeaders({
      'Content-Type': 'application/json'
    });

    return this.http.post<any>(this.apiUrl, trip, { headers })
      .pipe(
        catchError(this.handleError)
      );
  }

  // Update existing trip (protected endpoint - requires authentication)
  updateTrip(id: string, trip: Trip): Observable<any> {
    const headers = new HttpHeaders({
      'Content-Type': 'application/json'
    });

    return this.http.put<any>(`${this.apiUrl}/${id}`, trip, { headers })
      .pipe(
        catchError(this.handleError)
      );
  }

  // Partially update trip (protected endpoint - requires authentication)
  patchTrip(id: string, updates: Partial<Trip>): Observable<any> {
    const headers = new HttpHeaders({
      'Content-Type': 'application/json'
    });

    return this.http.patch<any>(`${this.apiUrl}/${id}`, updates, { headers })
      .pipe(
        catchError(this.handleError)
      );
  }

  // Delete trip (protected endpoint - requires authentication)
  deleteTrip(id: string): Observable<any> {
    return this.http.delete<any>(`${this.apiUrl}/${id}`)
      .pipe(
        catchError(this.handleError)
      );
  }

  // Error handling
  private handleError(error: any): Observable<never> {
    let errorMessage = 'An error occurred';
    
    if (error.error instanceof ErrorEvent) {
      // Client-side error
      errorMessage = `Error: ${error.error.message}`;
    } else {
      // Server-side error
      errorMessage = error.error?.message || `Error Code: ${error.status}\nMessage: ${error.message}`;
    }
    
    console.error('TripService Error:', error);
    return throwError(() => new Error(errorMessage));
  }
}

